  /// Dynamically generates a list of visually similar lookalikes for a target word.
  static List<String> generateLookalikes(String target, int count) {
    final List<String> lookalikes = [];
    final lowerTarget = target.toLowerCase();

    // Strategy 1: Find visually similar real words in the dictionary using character overlap and length match
    final dictionaryCandidates = dictionary.where((word) {
      final w = word.toLowerCase();
      if (w == lowerTarget) return false;
      // Must be of similar length (within 1-2 characters)
      final lenDiff = (w.length - lowerTarget.length).abs();
      if (lenDiff > 2) return false;

      // Count overlapping characters
      int overlap = 0;
      final targetChars = lowerTarget.split('');
      for (final char in w.split('')) {
        if (targetChars.contains(char)) {
          overlap++;
          targetChars.remove(char);
        }
      }
      // High overlap score
      final double overlapRatio = overlap / max(w.length, lowerTarget.length);
      return overlapRatio >= 0.55;
    }).toList();

    // Shuffle and pick some candidates
    dictionaryCandidates.shuffle();
    for (final cand in dictionaryCandidates) {
      if (lookalikes.length >= count) break;
      if (!lookalikes.contains(cand)) {
        lookalikes.add(cand);
      }
    }

    // Strategy 2: Programmatically generate mutations if we don't have enough dictionary matches
    int attempts = 0;
    while (lookalikes.length < count && attempts < 100) {
      attempts++;
      final mutation = _mutate(lowerTarget);
      if (mutation != lowerTarget && !lookalikes.contains(mutation) && mutation.isNotEmpty) {
        lookalikes.add(mutation);
      }
    }

    // Pad with random dictionary words if we're still short (extremely rare)
    if (lookalikes.length < count) {
      final padPool = [...dictionary]..shuffle();
      for (final word in padPool) {
        if (lookalikes.length >= count) break;
        if (word != lowerTarget && !lookalikes.contains(word)) {
          lookalikes.add(word);
        }
      }
    }

    return lookalikes.sublist(0, count);
  }

  /// Mutates a word slightly to produce a lookalike.
  static String _mutate(String word) {
    if (word.length < 2) return word;
    final List<String> chars = word.split('');
    final int choice = _random.nextInt(4);

    switch (choice) {
      case 0:
        // Swap adjacent characters (e.g., form -> from)
        final idx = _random.nextInt(chars.length - 1);
        final temp = chars[idx];
        chars[idx] = chars[idx + 1];
        chars[idx + 1] = temp;
        return chars.join('');
      case 1:
        // Substitute a character with a visually similar one
        final idx = _random.nextInt(chars.length);
        final current = chars[idx];
        final visualMap = {
          'a': ['o', 'e', 'u'],
          'e': ['a', 'c', 'o'],
          'i': ['l', '1', 't', 'j'],
          'l': ['i', 't', '1'],
          'o': ['a', 'e', 'u', 'c', '0'],
          'u': ['v', 'w', 'n', 'o'],
          'n': ['m', 'h', 'u'],
          'm': ['n', 'w'],
          'r': ['n', 'v'],
          't': ['l', 'f', 'i'],
          'h': ['n', 'b', 'k'],
          'b': ['d', 'h', 'p'],
          'd': ['b', 'q', 'p'],
          'p': ['q', 'g', 'b', 'd'],
        };
        if (visualMap.containsKey(current)) {
          final options = visualMap[current]!;
          chars[idx] = options[_random.nextInt(options.length)];
        } else {
          // Fallback to random vowel replacement
          final vowels = ['a', 'e', 'i', 'o', 'u'];
          chars[idx] = vowels[_random.nextInt(vowels.length)];
        }
        return chars.join('');
      case 2:
        // Append a common suffix letter
        final suffixes = ['s', 'y', 'e', 'd'];
        return word + suffixes[_random.nextInt(suffixes.length)];
      case 3:
      default:
        // Remove a character (if long enough)
        if (word.length > 3) {
          final idx = _random.nextInt(chars.length);
          chars.removeAt(idx);
          return chars.join('');
        }
        return word;
    }
  }

  /// Chooses a random word from the dictionary.
  static String getRandomWord() {
    return dictionary[_random.nextInt(dictionary.length)];
  }

  /// Generates a random phrase (Adjective + Noun)
  static String getRandomPhrase() {
    // Pick two random words of length >= 4
    final wordPool = dictionary.where((w) => w.length >= 4).toList();
    final first = wordPool[_random.nextInt(wordPool.length)];
    final second = wordPool[_random.nextInt(wordPool.length)];
    return '$first $second';
  }

  /// Generates lookalike options for a 2-word phrase.
  static List<String> generatePhraseLookalikes(String phrase, int count) {
    final parts = phrase.split(' ');
    if (parts.length != 2) {
      return generateLookalikes(phrase, count);
    }
    final first = parts[0];
    final second = parts[1];

    final List<String> lookalikes = [];

    // Generate lookalikes for first word and second word separately
    final firstLookalikes = generateLookalikes(first, count);
    final secondLookalikes = generateLookalikes(second, count);

    // Mix and match to generate phrase lookalikes
    // e.g., firstLookalike + second, first + secondLookalike, firstLookalike + secondLookalike
    for (int i = 0; i < count; i++) {
      if (lookalikes.length >= count) break;
      lookalikes.add('${firstLookalikes[i]} $second');

      if (lookalikes.length >= count) break;
      lookalikes.add('$first ${secondLookalikes[i]}');

      if (lookalikes.length >= count) break;
      lookalikes.add('${firstLookalikes[i]} ${secondLookalikes[i]}');
    }

    return lookalikes.sublist(0, count);
  }
